import { runPipeline } from './pipeline';
import { PipelineState } from './pipeline';

describe('pipeline', () => {
  test('handles concurrent state correctly', async () => {
    const state: PipelineState = { count: 0, results: [] };

    // Run both processes concurrently
    const [r1, r2] = await Promise.all([
      runPipeline(state),
      runPipeline(state)
    ]);

    // Verify state is correctly incremented
    expect(state.count).toBe(2);
    expect(r1).toBe('first-1');
    expect(r2).toBe('second-2');
